def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    # Coordinate-compress every boundary so each leaf is a run of cells with identical history.
    pts = {1, n + 1}
    for op in ops:
        pts.add(op[1])
        pts.add(op[2] + 1)
    p = sorted(pts)
    idx = {v: i for i, v in enumerate(p)}
    m = len(p) - 1  # number of leaves; leaf i covers cells [p[i], p[i+1])

    size = 4 * m
    kind = [0] * size  # 0 = no tag, 1 = assign, 2 = chmax
    val = [0] * size

    def apply(node, k, x):
        if k == 1:
            kind[node] = 1
            val[node] = x
        elif kind[node] == 0:
            kind[node] = 2
            val[node] = x
        else:
            # chmax on top of a pending tag: max(old, x) is correct for both assign and chmax
            val[node] = max(val[node], x)

    def push(node):
        if kind[node]:
            k, x = kind[node], val[node]
            apply(2 * node, k, x)
            apply(2 * node + 1, k, x)
            kind[node] = 0

    def update(node, lo, hi, a, b, k, x):
        if b <= lo or hi <= a:
            return
        if a <= lo and hi <= b:
            apply(node, k, x)
            return
        push(node)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, a, b, k, x)
        update(2 * node + 1, mid, hi, a, b, k, x)

    for op in ops:
        a = idx[op[1]]
        b = idx[op[2] + 1]
        if op[0] == 1:
            # paint: new colour = max(old, c), with blank treated as 0
            update(1, 0, m, a, b, 2, op[3])
        else:
            # erase: assign blank (0)
            update(1, 0, m, a, b, 1, 0)

    res = {}

    def collect(node, lo, hi):
        if hi - lo == 1:
            c = val[node] if kind[node] else 0
            if c:
                res[c] = res.get(c, 0) + (p[lo + 1] - p[lo])
            return
        push(node)
        mid = (lo + hi) // 2
        collect(2 * node, lo, mid)
        collect(2 * node + 1, mid, hi)

    collect(1, 0, m)
    return [[c, res[c]] for c in sorted(res)]
